import {STYLE,POLICY,uid,blankLibrary,assertSafe,characterText,validateCharacter,newPanel,buildEpisodePages,panelJob,panelPrompt,portraitPrompt,characterSeed,EPISODE_MAX_PANELS,EPISODE_MAX_PAGES,PAGE_MAX_PANELS,VERSION,hasTattoos,shouldDeferUpdateReload,recentUpdateReload,isAppShellCache,deleteCharacter,deleteSeries,deleteEpisode,standaloneImageJob,assetIds,STANDALONE_LIMIT} from './core.js';
import {getLibrary,saveLibrary,getAsset,putAsset,deleteAssets,rasterize,exportLibrary,importLibrary,listStandalone,putStandalone,deleteStandalone} from './db.js';
import {Provider,readSettings,writeSettings,localBase,pickerModels,modelLabel,referencePicker,isReferenceCapable,isCancelled,explainRequestError,imagePromptLimit,negativePromptFor,DEFAULT_LIKENESS_MODEL} from './provider.js';
import {runPanelBatch} from './batch.js';
import {BUBBLE_PRESETS,createBubble,renderLettering,seedBubbles,dragUpdate,applyBubbleElement,flipTail,setFontSize,coverRect,paintBubbles,tailMarkup} from './bubbles.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
let lib=blankLibrary(), settings=readSettings(), nav='library', sid=null,eid=null,tab='write',busy=false,draft=null,readerIndex=0,gallery=[],imageDraft={prompt:'',style:STYLE,cast:[]};
let persist=Promise.resolve(), saveTimer,noticeTimer,batchAbort=null,lettering=null,bubbleGesture=null,swRegistration=null,updateReloadArmed=false;const assetURLs=new Map();
const SW_RELOAD_KEY='cs_sw_reload';
const provider=new Provider(settings,ask,(message)=>notify(message));
function series(){return lib.series.find(s=>s.id===sid);}
function episode(){return series()?.episodes.find(e=>e.id===eid);}
function allPanels(e=episode()){return e?.pages?.flatMap(p=>p.panels)||[];}
function imageModelId(){return settings.likenessMode?(settings.likenessModel||DEFAULT_LIKENESS_MODEL):(settings.imageModel||'chroma');}
function charactersForPanel(panel){const allowed=episode()?.cast||[];const allow=new Set(allowed);const chosen=(Array.isArray(panel?.cast)?panel.cast:[]).filter(id=>allow.has(id));const ids=chosen.length?chosen:allowed;return lib.characters.filter(c=>ids.includes(c.id)&&allow.has(c.id));}
function panelImageJob(panel,scene){const chars=charactersForPanel(panel);const job=panelJob({...panel,prompt:scene,cast:chars.map(c=>c.id)},chars,series()?.style||'',{limit:imagePromptLimit(imageModelId(),provider.models),likeness:settings.likenessMode===true});return {chars,job};}
function lastBackupLabel(){const raw=localStorage.getItem('cs_last_backup');if(!raw)return 'No library backup has been exported from this browser yet.';const date=new Date(raw);if(Number.isNaN(date.getTime()))return 'Last backup date could not be read.';return `Last backup: ${date.toLocaleString()}`;}
function resumeLabel(){const panels=allPanels();if(!panels.length)return '';const done=panels.filter(p=>p.imageId).length;if(done>=panels.length)return '';return `Resume images (${done}/${panels.length})`;}
function selectedCharacters(ids=episode()?.cast||[]){return lib.characters.filter(c=>ids.includes(c.id));}
function panelById(id){return episode()?.pages.flatMap(p=>p.panels).find(x=>x.id===id);}
function notify(message,error=false,retry=null){const n=$('#notice');n.hidden=false;n.classList.toggle('error',!!error);n.setAttribute('role',error?'alert':'status');n.replaceChildren(document.createTextNode(message));if(retry){const b=document.createElement('button');b.type='button';b.className='small';b.textContent='Try again';b.addEventListener('click',ev=>{ev.stopPropagation();if(!busy)retry();});n.append(document.createElement('br'),b);}showDialogNotice(message,error);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{n.hidden=true;n.replaceChildren();},error?20000:6500);}
function showDialogNotice(message,error){for(const id of ['modal','lettering']){const dialog=document.getElementById(id);if(!dialog?.open)continue;let banner=dialog.querySelector('[data-dialog-notice]');if(!banner){banner=document.createElement('p');banner.dataset.dialogNotice='';banner.setAttribute('role','alert');}banner.className=error?'dialog-notice error':'dialog-notice';banner.hidden=false;banner.textContent=message;const actions=dialog.querySelector('.sticky-actions');if(actions)actions.prepend(banner);else (dialog.querySelector('#modalContent, #letteringContent')||dialog).prepend(banner);}}
function saving(text){$$('.save-status').forEach(n=>n.textContent=text);}
function save(){clearTimeout(saveTimer);saving('Saving on this device…');const snapshot=structuredClone(lib);persist=persist.catch(()=>{}).then(()=>saveLibrary(snapshot));persist.then(()=>saving('Saved on this device · back up regularly'),e=>{saving('Not saved — export a backup now');notify('Storage failed: '+e.message+' Your latest changes may not survive closing the app.',true);});return persist;}
function queueSave(){saving('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
async function flush(){clearTimeout(saveTimer);await save();await persist;}
function setBusy(v){busy=v;$$('[data-ai], [data-mutates], [data-action="import"], [data-action="export"]').forEach(b=>b.disabled=v);$('#modeBadge').textContent=v?'WORKING…':settings.demo?'OFFLINE DEMO':'LIVE MODE';}
async function run(fn,retry){if(busy)return;setBusy(true);try{await fn();}catch(e){if(isCancelled(e))notify(e.message||'Cancelled.');else{const raw=String(e?.message||'');const message=explainRequestError(e)||'Something went wrong. Try again.';notify(message,true,(e?.retryable||message!==raw)?retry:null);}}finally{setBusy(false);}}
function again(fn){const go=()=>run(fn,go);return go;}
function ask(title,message,label='Continue'){return new Promise(resolve=>{const d=document.createElement('dialog');d.setAttribute('aria-label',title);d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="sticky-actions"><button type="button" data-no class="secondary">Cancel</button><button type="button" data-yes>${esc(label)}</button></div>`;document.body.append(d);let done=false;const finish=v=>{if(done)return;done=true;d.close();d.remove();resolve(v);};d.querySelector('[data-no]').onclick=()=>finish(false);d.querySelector('[data-yes]').onclick=()=>finish(true);d.addEventListener('cancel',e=>{e.preventDefault();finish(false);});d.showModal();});}
function showModal(html){$('#modalContent').innerHTML=html;const d=$('#modal');if(!d.open)d.showModal();hydrate(d);}
function closeModal(){if($('#modal').open)$('#modal').close();draft=null;}
async function assetURL(id){if(!id)return null;if(assetURLs.has(id))return assetURLs.get(id);const a=await getAsset(id);if(!a)return null;const u=URL.createObjectURL(a.blob);assetURLs.set(id,u);return u;}
function hydrate(root=document){root.querySelectorAll('[data-image-id]').forEach(async n=>{try{const u=await assetURL(n.dataset.imageId);if(u){n.src=u;n.hidden=false;}}catch{notify('An image could not be loaded from device storage.',true);}});}
function refMarkup(id,cls='char-ref'){return id?`<img class="${cls}" data-image-id="${esc(id)}" alt="Fictional character reference artwork" hidden>`:'';}
async function forgetAssets(ids){const list=[...new Set((ids||[]).filter(Boolean))];for(const id of list){const url=assetURLs.get(id);if(url){URL.revokeObjectURL(url);assetURLs.delete(id);}}if(list.length)await deleteAssets(list);}
function dismissDeleted(){if(episode())return;const reader=document.getElementById('reader');if(reader?.open)reader.close();if(!lettering)return;lettering=null;bubbleGesture=null;const dialog=document.getElementById('lettering');if(dialog?.open)dialog.close();}
function render(){
  readImageDraft();
  $$('.bottom-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));
  if(nav==='settings')$('#app').innerHTML=settingsView();else if(nav==='characters')$('#app').innerHTML=charactersView();else if(nav==='images')$('#app').innerHTML=imagesView();else if(episode())$('#app').innerHTML=episodeView();else if(series())$('#app').innerHTML=seriesView();else $('#app').innerHTML=libraryView();
  setBusy(busy);hydrate($('#app'));
}
function readImageDraft(){const prompt=document.querySelector('[data-image-prompt]');if(!prompt)return imageDraft;const style=document.querySelector('[data-image-style]');const boxes=[...document.querySelectorAll('[data-image-cast]')];imageDraft={prompt:prompt.value,style:style?style.value:imageDraft.style,cast:boxes.length?boxes.filter(n=>n.checked).map(n=>n.value):imageDraft.cast};return imageDraft;}
function imagesView(){const picked=imageDraft.cast||[];const latest=gallery[0];const cast=lib.characters.length?`<label>Characters</label><p class="muted">Only checked characters are drawn, the same way a panel uses its cast. Leave them unchecked to use the prompt alone.</p>${castCheckboxes(picked,'data-image-cast')}`:`<p class="muted">No saved characters yet. You can still generate from the prompt.</p>${button('Create a character','new-character','secondary','data-mutates')}`;const preview=latest?`<div class="panel-art image-preview"><img data-image-id="${esc(latest.imageId)}" alt="Generated image" hidden></div><div class="row">${button('↓ Save','download-image','secondary',`data-id="${esc(latest.id)}"`)}${button('Delete','delete-image','danger',`data-id="${esc(latest.id)}" data-mutates`)}</div><p class="muted">${esc(latest.prompt)}</p>`:`<div class="panel-art image-preview"><div class="placeholder"><span class="symbol">✧</span><span>Your image will show up here</span><small>Same size as a panel, 832×1216</small></div></div>`;const older=gallery.slice(1);const cards=older.map(shot=>{const names=(shot.cast||[]).map(id=>lib.characters.find(c=>c.id===id)?.name).filter(Boolean);return `<article class="card image-card"><div class="panel-art"><img data-image-id="${esc(shot.imageId)}" alt="Saved generated image" hidden></div><div class="image-card-body"><p>${esc(String(shot.prompt||'').slice(0,160))}</p>${names.length?`<p class="pill">${esc(names.join(', '))}</p>`:''}<div class="row">${button('↓ Save','download-image','secondary',`data-id="${esc(shot.id)}"`)}${button('Delete','delete-image','danger',`data-id="${esc(shot.id)}" data-mutates`)}</div></div></article>`;}).join('');return `<p class="eyebrow">A picture of its own</p><div class="section-heading"><h1>Images</h1><span class="pill">NOT A STORY</span></div><p class="muted">Generate one image without a series or an episode. It uses the same models, mature-adult wording, and content blocks as a panel.</p><form id="imageForm" class="card">${area('Prompt','imagePrompt',imageDraft.prompt,'data-image-prompt maxlength="5000" placeholder="Two fictional adults on a moonlit balcony, amber light, quiet and close."')}${cast}${area('Art style','imageStyle',imageDraft.style,'data-image-style maxlength="5000"')}<p class="muted">Optional, prefilled with the studio default. Pictures are 832×1216, the same size as a panel. Likeness mode in Settings applies when a checked character has an approved portrait.</p>${button('Generate image','generate-image','','data-ai')}</form><section data-image-result><div class="section-heading"><h2>Latest</h2></div>${preview}</section><div class="section-heading"><h2>Saved on this device <span class="muted">${gallery.length}</span></h2></div>${older.length?`<div class="grid">${cards}</div>`:gallery.length?'<p class="muted">Saved on this device, separate from every series.</p>':'<div class="empty"><h3>Nothing saved yet</h3><p>Images you generate here stay on this device and never show up inside a series.</p></div>'}`;}
function libraryView(){return `<section class="hero"><div class="hero-text"><p class="eyebrow">Your worlds, together</p><h1>A little imagination.<br>A whole new world.</h1><p>Create a cast. Write your story. Turn it into a comic you can keep coming back to.</p>${button('＋ New series','new-series','', 'data-mutates')}</div><div class="hero-art" aria-hidden="true"><span class="big-star">✦</span><div><p class="eyebrow">Made by the two of you</p><h2>Every great story<br>starts with “what if?”</h2></div></div></section><div class="section-heading"><h2>Your library <span class="muted">${lib.series.length}</span></h2><span class="pill">ON THIS DEVICE</span></div>${lib.series.length?`<div class="grid">${lib.series.map(s=>`<article class="card series-card"><div class="series-cover"><h3>${esc(s.title)}</h3></div><div class="series-info"><p>${esc(s.synopsis||'Your next story is waiting.')}</p><div class="row between"><span class="pill">${s.episodes.length} EPISODE${s.episodes.length===1?'':'S'}</span><span class="muted">Ongoing series</span></div><br>${button('Open series →','open-series','secondary',`data-id="${s.id}"`)}</div></article>`).join('')}</div>`:`<div class="empty"><h3>Your shelf is a blank canvas.</h3><p>Start a series or explore a fictional sample.</p>${button('Try a sample story','sample','secondary','data-mutates')}</div>`}<p class="status-line">Private by default: no sign-in, tracking, or automatic API requests. Mature and explicit stories between consenting fictional adults 18+.</p>`;}
function charactersView(){return `<p class="eyebrow">The cast behind the story</p><div class="section-heading"><h1>Your characters</h1>${button('＋ New','new-character','','data-mutates')}</div><p class="muted">Save their look, personality, and past. Their profiles travel with each story request.</p>${lib.characters.length?`<div class="grid">${lib.characters.map(c=>`<article class="card"><div class="char-preview">${(c.portraitId||c.refId)?refMarkup(c.portraitId||c.refId,'avatar'):`<div class="avatar">${esc(String(c.name||'?')[0]||'?')}</div>`}<div><h3>${esc(c.name)}</h3><span class="pill">FICTIONAL · ${c.age}+</span></div></div><p class="muted" style="margin:15px 0">${esc(String(c.description||'').slice(0,180))}</p><div class="row">${button('Edit character','edit-character','secondary',`data-id="${c.id}" data-mutates`)}${button('Delete character','delete-character','danger',`data-id="${c.id}" data-mutates`)}</div></article>`).join('')}</div>`:`<div class="empty"><h3>Who lives in your world?</h3><p>Describe a fictional adult, choose presets, or upload a reference sheet.</p>${button('Create your first character','new-character','','data-mutates')}</div>`}`;}
function seriesView(){const s=series();return `${button('← Your library','back-library','back')}<p class="eyebrow">Ongoing series</p><h1>${esc(s.title)}</h1><p class="muted">${esc(s.synopsis)}</p><div class="toolbar">${button('＋ New episode','new-episode','','data-mutates')}${button('Series & art style','edit-series','secondary','data-mutates')}</div><div class="section-heading"><h2>Episodes</h2><span class="muted">${s.episodes.length} chapters so far</span></div>${s.episodes.length?s.episodes.map((e,i)=>`<article class="card episode-row"><div><span class="eyebrow">EPISODE ${String(i+1).padStart(2,'0')}</span><h3>${esc(e.title)}</h3><small>${e.pages.length} pages · ${e.pages.reduce((n,p)=>n+p.panels.length,0)} panels</small></div>${button('Open →','open-episode','secondary',`data-id="${e.id}"`)}</article>`).join(''):'<div class="empty">Your first episode starts here. Write a scene, then let AI propose a storyboard.</div>'}<details><summary>Art direction</summary><p class="muted">${esc(s.style)}</p></details><div class="card danger-zone"><h2>Delete series</h2><p class="muted">Removes this series and every episode in it. Characters stay in your library.</p>${button('Delete series','delete-series','danger','data-mutates')}</div><p class="status-line save-status">Saved on this device · back up regularly</p>`;}
function castCheckboxes(ids,attrs=''){return `<div class="cast">${lib.characters.map(c=>`<label class="check"><input type="checkbox" value="${c.id}" ${ids.includes(c.id)?'checked':''} ${attrs}>${esc(c.name)} <small>${c.age}</small></label>`).join('')}</div>`;}
function episodeView(){const e=episode(),s=series();const resume=resumeLabel();return `${button('← '+esc(s.title),'back-series','back')}<p class="eyebrow">The episode studio</p><h1>${esc(e.title)}</h1><div class="tabs" role="tablist" aria-label="Episode workspace"><button role="tab" aria-selected="${tab==='write'}" class="${tab==='write'?'active':''}" data-tab="write">Write</button><button role="tab" aria-selected="${tab==='panels'}" class="${tab==='panels'?'active':''}" data-tab="panels">Storyboard</button><button role="tab" aria-selected="false" data-action="read">Read ↗</button></div>${tab==='write'?`<div class="card">${input('Episode title','episodeTitle',e.title,'text','data-bind="episode-title" maxlength="200"')}<label>Characters in this episode</label>${lib.characters.length?castCheckboxes(e.cast,'data-bind="episode-cast"'):`<p class="muted">Create at least one fictional adult character before using AI.</p>${button('Create a character','new-character','secondary','data-mutates')}`}${area('Your script','script',e.script,'data-bind="script" rows="14" maxlength="60000" placeholder="Write the scene in your own words. Add dialogue, action, and atmosphere…"')}<p class="muted">You write the story. Generate comic keeps your beats in order and does not rewrite them. Polish is optional and changes the script only if you apply it.</p><div class="toolbar">${button('✦ AI polish','polish','','data-ai')}${button('Lay out from script','plan','secondary','data-mutates')}${button('✦ Generate comic','generate-comic','','data-ai')}${resume?button(resume,'resume-comic','secondary','data-ai'):''}${e.previousScript?button('Undo last polish','undo-polish','ghost','data-mutates'):''}</div><p class="save-status status-line">Saved on this device · back up regularly</p></div>`:panelsView()}<div class="card danger-zone"><h2>Delete episode</h2><p class="muted">Removes this episode and its panel art. The series and your characters stay.</p>${button('Delete episode','delete-episode','danger','data-mutates')}</div><div class="help">${settings.demo?'Offline demo is on. AI buttons return local sample responses; no network calls or credits.':'Live mode: writing streams from Venice. Keep this screen open and unlocked until the reply finishes. Images prefer your local server if configured. A full comic asks once, then illustrates each panel in order. You can cancel and resume.'}</div>`;}
function preview(p,opts={}){const lettering=Array.isArray(p.bubbles)&&p.bubbles.length?renderLettering(p.bubbles):'';const edit=opts.edit&&p.imageId?`<button type="button" class="bubble-jump" data-action="edit-bubbles" data-id="${esc(p.id)}">Bubbles</button>`:'';return `${p.imageId?`<img data-image-id="${esc(p.imageId)}" alt="Generated comic panel" hidden>`:`<div class="placeholder"><span class="symbol">✧</span><span>${esc(p.camera||'Your next scene')}</span><small>Generate this panel to add art</small></div>`}${lettering}${edit}`;}
function panelCard(p,pi){return `<article class="panel-card" data-panel="${p.id}"><div class="panel-art" data-preview="${p.id}">${preview(p)}</div><div class="panel-fields"><div class="row between"><strong>Panel ${pi+1}</strong>${button('Remove','remove-panel','ghost small',`data-id="${p.id}" data-mutates`)}</div><label>Camera / angle<input data-panel-field="camera" data-id="${p.id}" value="${esc(p.camera)}" list="cameraAngles" maxlength="200"></label><label>Scene prompt<textarea data-panel-field="prompt" data-id="${p.id}" maxlength="5000">${esc(p.prompt)}</textarea></label><details><summary>Characters & lettering</summary><label>Characters in this panel</label>${castCheckboxes(p.cast,`data-panel-cast="${p.id}"`)}<label>Dialogue notes · not drawn on the picture<textarea data-panel-field="dialogue" data-id="${p.id}" maxlength="2000">${esc(p.dialogue)}</textarea></label><label>Bubble position<select data-panel-field="bubblePosition" data-id="${p.id}"><option value="top" ${p.bubblePosition==='top'?'selected':''}>Top</option><option value="bottom" ${p.bubblePosition==='bottom'?'selected':''}>Bottom</option></select></label><label>Caption<textarea data-panel-field="caption" data-id="${p.id}" maxlength="1000">${esc(p.caption)}</textarea></label><label>Caption position<select data-panel-field="captionPosition" data-id="${p.id}"><option value="bottom" ${p.captionPosition==='bottom'?'selected':''}>Bottom</option><option value="top" ${p.captionPosition==='top'?'selected':''}>Top</option></select></label></details><p class="muted">Text stays editable. Regenerate art after changing the scene or cast.</p>${p.genError&&!p.imageId?`<p class="error-note">${esc(p.genError)}</p>`:''}${button(p.imageId?'↻ Regenerate this panel':'✦ Generate this panel','generate-panel','',`data-id="${p.id}" data-ai`)}${p.imageId?button('Speech bubbles','edit-bubbles','secondary',`data-id="${p.id}"`):''}${p.cast.filter(i=>lib.characters.find(c=>c.id===i)?.refId).length>1?'<p class="muted">Local face conditioning uses the first character reference only.</p>':''}</div></article>`;}
function panelsView(){const e=episode();const panels=allPanels(e);const done=panels.filter(p=>p.imageId).length;const resume=resumeLabel();return `<div class="toolbar">${button('Lay out from script','plan','secondary','data-mutates')}${button('✦ Generate comic','generate-comic','','data-ai')}${resume?button(resume,'resume-comic','secondary','data-ai'):''}${button('＋ Blank page','add-page','secondary','data-mutates')}${button('Read episode','read','secondary')}</div><p class="muted">${panels.length?`${done}/${panels.length} panels illustrated. `:''}Each sentence becomes one panel, in the order you wrote it. Dialogue is lettered on top by the app. Cancel anytime and resume without redoing finished art.</p><datalist id="cameraAngles"><option value="Wide establishing shot"><option value="Medium shot, eye level"><option value="Close-up, three-quarter view"><option value="Over the shoulder"><option value="Low angle"><option value="Bird’s-eye view"></datalist>${e.pages.length?e.pages.map((p,i)=>`<section class="card"><div class="row between"><h2>Page ${i+1}</h2><label style="margin:0">Layout<select data-page-layout="${p.id}" aria-label="Page ${i+1} layout"><option value="single" ${p.layout==='single'?'selected':''}>Single column</option><option value="two" ${p.layout==='two'?'selected':''}>Two columns</option><option value="hero" ${p.layout==='hero'?'selected':''}>Hero + grid</option></select></label></div><div class="panel-list" style="margin-top:16px">${p.panels.map(panelCard).join('')}</div><div class="row">${button('＋ Add panel','add-panel','secondary small',`data-id="${p.id}" data-mutates`)}${button('Remove page','remove-page','ghost small',`data-id="${p.id}" data-mutates`)}</div></section>`).join(''):'<div class="empty"><h3>From words to frames.</h3><p>Plan pages from your script, or add a blank page to build your own layout.</p></div>'}<p class="save-status status-line">Saved on this device · back up regularly</p>`;}
function settingsView(){return `<p class="eyebrow">Your studio, your rules</p><h1>Settings</h1><form id="settingsForm"><section class="card"><h2>Connections</h2><label class="check"><input name="demo" type="checkbox" ${settings.demo?'checked':''}>Offline demo mode · no API calls</label><p class="muted">Turn off only when you’re ready to use your own services. No paid requests are sent without a confirmation.</p><p class="muted">Generate comic follows your script: one panel per sentence, in reading order. It does not pad the story to a fixed panel count.</p>${input('Venice API key','veniceKey',localStorage.getItem('cs_k')||'','password','autocomplete="off" spellcheck="false"')}<p class="muted">Stored only in this browser, never in backups. It is not encrypted; use a trusted device and host.</p>${input('Local image server URL · optional','localURL',settings.localURL,'url','placeholder="https://your-private-tunnel.example" autocomplete="off"')}${input('Local server bearer token · optional, separate from Venice','localKey',localStorage.getItem('cs_local_k')||'','password','autocomplete="off" spellcheck="false"')}<p class="muted">Your PC must be on. The phone needs a reachable HTTPS endpoint with CORS enabled. The Venice key is never sent to your local server.</p><label class="check"><input name="allowCloudFallback" type="checkbox" ${settings.allowCloudFallback?'checked':''}>Offer Venice fallback if local rendering fails</label><p class="muted">Local is preferred whenever set. Fallback is off by default and still asks before spending.</p></section><section class="card"><h2>Models</h2>${input('Text model · most_uncensored is the best fit for adult fiction','textModel',settings.textModel,'text','list="textModels" maxlength="150"')}${input('Image model · Chroma text-only path','imageModel',settings.imageModel,'text','list="imageModels" maxlength="150"')}<label class="check"><input name="likenessMode" type="checkbox" ${settings.likenessMode?'checked':''}>Likeness portraits · send each approved portrait with the panel</label><p class="muted">Off keeps Chroma text-only. Chroma does not receive reference images. On uses the reference model below, and each paid image still asks first.</p>${input('Likeness model · reference images','likenessModel',settings.likenessModel||'qwen-edit-uncensored','text','list="likenessModels" maxlength="150"')}<datalist id="textModels">${pickerModels(provider.models,'text').map(m=>`<option value="${esc(m.id)}">${esc(modelLabel(m))}</option>`).join('')}</datalist><datalist id="imageModels">${pickerModels(provider.models,'image').map(m=>`<option value="${esc(m.id)}">${esc(modelLabel(m))}</option>`).join('')}</datalist><datalist id="likenessModels">${referencePicker(provider.models).map(m=>`<option value="${esc(m.id)}">${esc(modelLabel(m))}</option>`).join('')}</datalist><div class="row"><button type="submit">Save settings</button>${button('Load available models','load-models','secondary','data-ai')}</div><p class="muted">Load available models to fill the likeness list with edit models and models that advertise style references. The default, qwen-edit-uncensored, is the edit model documented for uncensored output. safe_mode is false. Other edit models accept that flag but may still block adult prompts. Two portraits are sent separately when the model allows more than one input image; otherwise they are combined side by side.</p><p class="muted" id="modelsStatus">${provider.models.length?`${provider.models.length} active models loaded. ${provider.models.filter(isReferenceCapable).length} can take reference images. Deprecated models excluded.`:'Model discovery runs only when you ask. Save settings before loading.'}</p></section></form><section class="card"><h2>Library backup</h2><p class="muted">Characters, reference art, scripts, layouts, panel art, and standalone images in one JSON file. Keys and connection settings are excluded. Keep backups private: they contain your stories and images.</p><p class="muted" id="lastBackup">${esc(lastBackupLabel())}</p><div class="row">${button('↓ Export library','export','','data-mutates')}${button('↑ Import backup','import','secondary','data-mutates')}</div><input type="file" id="importFile" accept="application/json,.json" hidden><p class="muted" style="margin-top:12px">Import replaces this device’s stories after confirmation. Standalone images are replaced when the backup includes them, and kept when an older backup does not. Export first if you want a copy.</p></section><section class="card"><h2>Privacy & content</h2><p class="muted">Your library stays in IndexedDB on this device. It isn’t a synced account or encrypted vault. Other people using this browser profile can open it. Clearing website data deletes it.</p><p class="muted">AI writing sends selected character profiles and your episode to Venice. Image generation sends the scene prompt and supported reference art to the chosen provider. No auto-illustration, analytics, or background paid tasks.</p><p class="settings-warning">Fictional adults 18+ only. Explicit adult content and nudity between consenting fictional adults is allowed. Minors, age ambiguity, real identifiable people, bestiality, and non-consent are blocked. Venice image requests use safe_mode: false, and uncensored models are listed first.</p><p class="muted">Client-side content checks are a guardrail, not tamper-proof moderation. A hosted production API also needs server-side checks.</p></section><section class="card"><h2>Put it on your home screen</h2><p class="muted">Open the HTTPS-hosted app in Safari, tap Share, then Add to Home Screen. The interface and existing library work offline. AI needs internet or your reachable local server.</p>${button('Request persistent device storage','persist-storage','secondary')}<p class="muted" id="storageStatus">Browser storage is best-effort. Keep exported backups even with persistence.</p></section><section class="card"><h2>Updates</h2><p class="muted">Check for updates downloads the latest app files and clears the saved page cache only. Your library, images, and keys stay on this device.</p>${button('Check for updates','check-updates','secondary')}</section><p class="status-line">Comic Studio v${VERSION} · local-first · no account needed</p>`;}
function seriesForm(existing){const s=existing||{title:'',synopsis:'',style:STYLE};showModal(`<form id="seriesForm" data-id="${existing?.id||''}"><div class="modal-title"><h2>${existing?'Series settings':'Start a new series'}</h2>${button('✕','close','ghost','aria-label="Close"')}</div>${input('Series title','title',s.title,'text','required maxlength="200" placeholder="The world you’re about to create"')}${area('Premise / synopsis','synopsis',s.synopsis,'maxlength="5000"')}${area('Art style · used in every panel','style',s.style,'required maxlength="5000"')}<p class="muted">Default: stylized 3D animated film look with mature adult faces, realistic skin, and cinematic lighting. Change it for this series only.</p>${existing?`<div class="card danger-zone"><h3>Delete series</h3><p class="muted">Removes this series, its episodes, and panel art that belongs only to it. Characters stay in your library.</p>${button('Delete series','delete-series','danger','data-mutates')}</div>`:''}<div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit">${existing?'Save series':'Create series'}</button></div></form>`);}
function episodeForm(){showModal(`<form id="episodeForm"><div class="modal-title"><h2>A new chapter</h2>${button('✕','close','ghost','aria-label="Close"')}</div>${input('Episode title','title','','text','required maxlength="200" placeholder="Episode '+(series().episodes.length+1)+'"')}<p class="muted">You can write the script and select characters on the next screen.</p><div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit">Create episode</button></div></form>`);}
function characterForm(c){draft=structuredClone(c||{id:uid(),name:'',age:30,fictional:false,description:'',personality:'',backstory:'',body:'',hair:'',outfit:'',tattoos:'',refId:null,portraitId:null});if(draft.portraitId===undefined)draft.portraitId=null;drawCharacterForm();}
function characterUnsaved(c){const saved=lib.characters.find(x=>x.id===c.id);if(!saved)return !!(String(c.name||'').trim()||String(c.description||'').trim()||String(c.personality||'').trim()||String(c.backstory||'').trim()||String(c.body||'').trim()||String(c.hair||'').trim()||String(c.outfit||'').trim()||String(c.tattoos||'').trim()||c.refId||c.portraitId||c.fictional);for(const k of ['name','age','fictional','description','personality','backstory','body','hair','outfit','tattoos','refId','portraitId'])if(saved[k]!==c[k])return true;return false;}
function drawCharacterForm(){const c=draft;showModal(`<form id="characterForm"${characterUnsaved(c)?' data-dirty="1"':''}><div class="modal-title"><h2>${lib.characters.some(x=>x.id===c.id)?'Edit character':'Meet someone new'}</h2>${button('✕','close','ghost','aria-label="Close"')}</div><div class="row"><div class="grow">${input('Name','name',c.name,'text','required maxlength="100"')}</div><div style="width:100px">${input('Age · 18+','age',c.age,'number','required min="18" max="150" step="1"')}</div></div><label class="check"><input name="fictional" type="checkbox" ${c.fictional?'checked':''} required>This is a fictional adult, age 18 or older. Uploaded art depicts only fictional adults.</label>${area('Appearance / visual description','description',c.description,'required maxlength="8000" placeholder="Distinctive face, eyes, build, colors, and other details…"')}<details><summary>Quick appearance presets</summary><label>Starting look<select id="appearancePreset"><option value="">Choose a preset…</option><option value="explorer">Cinematic explorer</option><option value="noir">Neon noir detective</option><option value="artist">Off-duty artist</option></select></label>${input('Body / build','body',c.body,'text','maxlength="1000"')}${input('Hair','hair',c.hair,'text','maxlength="1000"')}${input('Outfit','outfit',c.outfit,'text','maxlength="1000"')}${input('Tattoos / markings','tattoos',c.tattoos,'text','maxlength="2000"')}</details>${area('Personality / voice','personality',c.personality,'maxlength="8000" placeholder="What are they like? How do they speak?"')}${area('Backstory / relationships','backstory',c.backstory,'maxlength="8000" placeholder="Their history, motives, and relationships…"')}<hr><h3>Identity reference</h3><p class="muted">Upload fictional character art or a front / side / back turnaround. Multi-view sheets are saved as one identity reference.</p>${refMarkup(c.refId)}<label>Upload reference art<input id="referenceFile" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted">JPEG, PNG, or WebP up to 20 MB. Images are resized to 1536 px. Do not upload real-person likenesses.</p><div class="row">${button('✦ Generate reference sheet','generate-reference','secondary','data-ai')}${c.refId?button('Remove reference','remove-reference','ghost','data-mutates'):''}</div><p class="help">Reference sheets guide the look. They are not the likeness portrait.</p><hr><h3>Likeness portrait</h3><p class="muted">One approved front portrait. Likeness mode sends it with every panel so the face, hair, and tattoos stay the same.</p>${refMarkup(c.portraitId)}<label>Upload a portrait<input id="portraitFile" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="row">${button('✦ Generate from description','generate-portrait','secondary','data-ai')}${c.refId&&c.refId!==c.portraitId?button('Use reference art','use-reference-portrait','secondary','data-mutates'):''}${c.portraitId?button('Remove portrait','remove-portrait','ghost','data-mutates'):''}</div><p class="help">Saving the character approves this portrait. Export a library backup afterward. Do not upload a real person’s likeness.</p>${lib.characters.some(x=>x.id===c.id)?`<div class="card danger-zone"><h3>Delete character</h3><p class="muted">Removes this character from your library and from every episode and panel cast. Panel art stays.</p>${button('Delete character','delete-character','danger',`data-id="${c.id}" data-mutates`)}</div>`:''}<div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit" data-mutates>Save character</button></div></form>`);setBusy(busy);}
function collectCharacter(){const f=new FormData($('#characterForm'));const c={...draft,age:Number(f.get('age')),fictional:f.has('fictional')};for(const k of ['name','description','personality','backstory','body','hair','outfit','tattoos'])c[k]=String(f.get(k)||'').trim();return c;}
function requireStory(){const e=episode();if(!e.script.trim())throw Error('Write your episode first.');const chars=selectedCharacters();if(!chars.length)throw Error('Choose at least one fictional adult character for the episode.');assertSafe([series().title,series().synopsis,series().style,e.title,e.script,...chars.map(characterText)].join('\n'),chars);return chars;}
async function polish(){const chars=requireStory(),e=episode();const result=await provider.text('polish',{title:e.title,script:e.script,series:series().synopsis,characters:chars.map(c=>({id:c.id,profile:characterText(c)}))},chars);showModal(`<div class="modal-title"><h2>Review the polish</h2>${button('✕','close','ghost','aria-label="Close"')}</div><p class="muted">Your original stays untouched until you apply this version.</p><label>Proposed script<textarea id="polishResult" rows="17" maxlength="60000">${esc(result)}</textarea></label><div class="sticky-actions">${button('Keep original','close','secondary')}${button('Apply polish','apply-polish','')}</div>`);}
async function plan(){const chars=requireStory(),e=episode();if(e.pages.length&&!await ask('Replace this storyboard?','This lays your script out in reading order, one panel per beat. It does not rewrite your words or call Venice. Panel art on these pages will be cleared.','Replace pages'))return;e.pages=buildEpisodePages({script:e.script,cast:chars.map(c=>c.id),characters:chars});await save();tab='panels';render();notify('Storyboard follows your script. Your words were not rewritten.');}
async function generatePanel(id){const p=panelById(id);if(!p)throw Error('Panel not found.');const scene=String(p.prompt||'').trim();if(!scene&&!(p.bubbles||[]).length)throw Error('Add a scene prompt first.');const {chars,job}=panelImageJob(p,scene);if(!chars.length)throw Error('Choose at least one fictional adult character for this episode.');const all=[series().style,series().synopsis,episode().script,scene,p.camera,...chars.map(characterText)].join('\n');assertSafe(all,chars);const blob=await provider.image(job.prompt,job.referenceIds,job.characters,{seed:job.seed,portraitIds:settings.likenessMode?job.portraitIds:[]});p.imageId=await putAsset(blob);p.genError=undefined;await save();render();notify(settings.demo?'Demo panel created locally. No credits used.':'Panel saved on this device.');}
function showBatch(completed,total,note=''){const el=$('#batchStatus');if(!el)return;el.hidden=false;$('#batchCount').textContent=`${completed}/${total}`;const bar=$('#batchProgress');bar.max=String(total||1);bar.value=String(completed);$('#batchNote').textContent=note||'';}
function hideBatch(){const el=$('#batchStatus');if(el)el.hidden=true;}
function paintPanel(p){document.querySelectorAll(`[data-preview="${p.id}"]`).forEach(node=>{node.innerHTML=preview(p,{edit:!!node.closest('#reader')});hydrate(node);});}
async function generateComic(resume){try{if(resume){if(!allPanels().length)throw Error('Generate the comic first, then resume any panels that do not have art yet.');await illustrateEpisode();return;}const chars=requireStory();const e=episode();const pages=buildEpisodePages({script:e.script,cast:chars.map(c=>c.id),characters:chars});const count=pages.reduce((n,page)=>n+page.panels.length,0);const existing=allPanels().length;if(existing&&!await ask('Replace this storyboard?',`This follows your script in order: ${count} panel${count===1?'':'s'}, one per beat. It does not rewrite your words. The current ${existing} panel${existing===1?'':'s'} and their art will be replaced.`,'Replace and generate'))return;e.pages=pages;await save();tab='panels';render();await illustrateEpisode();}finally{if(!batchAbort)hideBatch();}}
async function illustrateEpisode(){const e=episode();const panels=allPanels(e);const pending=panels.filter(p=>!p.imageId);if(!pending.length){notify('Every panel already has art.');return;}if(!settings.demo){if(!settings.localURL&&!localStorage.getItem('cs_k'))throw Error('Add a Venice API key or a local image server before generating panels.');const where=settings.localURL?'your local image server':settings.likenessMode?`Venice likeness mode (${settings.likenessModel||DEFAULT_LIKENESS_MODEL})`:'Venice';if(!await ask('Generate panel images?',`${pending.length} image request${pending.length===1?'':'s'} will run one at a time on ${where}. Only the characters checked for this episode are sent, and only the ones named in a beat when the beat names someone. Finished panels are kept if you cancel.`,'Start images')){notify(`Image generation cancelled. ${panels.length-pending.length}/${panels.length} panels already have art. Resume to continue.`);return;}}tab='panels';if(!document.querySelector(`[data-preview="${panels[0]?.id||''}"]`))render();batchAbort=new AbortController();const signal=batchAbort.signal;showBatch(panels.length-pending.length,panels.length,'Starting…');try{const result=await runPanelBatch({panels,shouldCancel:()=>signal.aborted,generate:async p=>{const scene=(p.prompt||'').trim();if(!scene&&!(p.bubbles||[]).length)throw Error('This panel has no scene prompt.');const {chars,job}=panelImageJob(p,scene);if(!chars.length)throw Error('Choose at least one fictional adult character for this episode.');assertSafe([series().style,series().synopsis,e.script,scene,p.camera,...chars.map(characterText)].join('\n'),chars);return provider.image(job.prompt,job.referenceIds,job.characters,{signal,approved:true,seed:job.seed,portraitIds:settings.likenessMode?job.portraitIds:[]});},save:async(panel,blob)=>{const imageId=await putAsset(blob);panel.imageId=imageId;panel.genError=undefined;await save();paintPanel(panel);return imageId;},onProgress:({completed,total,state,error})=>{const note=state==='failed'?(error||'A panel failed. Resume will retry it.'):state==='panel'?'Rendering the next panel…':'';showBatch(completed,total,note);}});const done=result.completed;if(result.cancelled)notify(`Stopped at ${done}/${result.total}. Resume to continue without redoing finished panels.`);else if(result.failed)notify(`${done}/${result.total} panels saved. ${result.failed} failed — Resume retries only those.`);else notify(settings.demo?`Demo comic ready, ${done}/${result.total} panels, no credits used.`:`Comic saved on this device, ${done}/${result.total} panels.`);}finally{batchAbort=null;hideBatch();render();}}
function syncBubbles(){if(!lettering)return;const panel=panelById(lettering.panelId);if(!panel)return;panel.bubbles=lettering.bubbles.map(b=>({...b}));const letterDialog=document.getElementById('lettering');if(letterDialog)letterDialog.dataset.dirty='1';queueSave();document.querySelectorAll(`[data-preview="${panel.id}"]`).forEach(node=>{if(node.closest('#lettering'))return;node.innerHTML=preview(panel,{edit:!!node.closest('#reader')});hydrate(node);});}
function markBubbleSelection(){document.querySelectorAll('#lettering [data-bubble-id]').forEach(n=>n.classList.toggle('selected',n.dataset.bubbleId===lettering?.selected));const selected=lettering?.bubbles.find(b=>b.id===lettering.selected);const font=document.querySelector('[data-bubble-font]');const flip=document.querySelector('[data-action="flip-tail"]');const del=document.querySelector('[data-action="delete-bubble"]');if(font){font.disabled=!selected;if(selected)font.value=String(selected.fontSize);}if(flip)flip.disabled=!selected;if(del)del.disabled=!selected;}
function drawBubbleEditor(){const panel=panelById(lettering.panelId);const presets=BUBBLE_PRESETS.map(p=>`<button type="button" class="preset" data-action="add-bubble" data-preset="${esc(p.id)}"><img alt="" src="${esc(p.src)}"><span>${esc(p.name)}</span></button>`).join('');const selected=lettering.bubbles.find(b=>b.id===lettering.selected);$('#letteringContent').innerHTML=`<div class="lettering-top"><div><p class="eyebrow" style="margin:0">Lettering</p><strong>Speech bubbles</strong></div>${button('Done','close-lettering','')}</div><div class="bubble-stage" data-bubble-stage><img class="panel-photo" data-image-id="${esc(panel.imageId)}" alt="Comic panel">${renderLettering(lettering.bubbles,{interactive:true,selected:lettering.selected})}</div><div class="preset-row" role="list">${presets}</div><div class="row bubble-tools"><label class="grow">Font size<input type="range" min="0.02" max="0.12" step="0.002" value="${selected?.fontSize??0.042}" data-bubble-font ${selected?'':'disabled'}></label>${button('Flip tail','flip-tail','secondary',selected?'':'disabled')}${button('Delete','delete-bubble','danger',selected?'':'disabled')}</div><p class="muted">Drag the bubble or the ✥ handle to place it. Drag the teal dot to aim the tail, and the corner to resize. Tap the words to type. Touch works the same as a mouse.</p>`;hydrate($('#lettering'));bindBubbleStage($('#lettering [data-bubble-stage]'));}
function bindBubbleStage(stage){if(!stage||stage.dataset.bound)return;stage.dataset.bound='1';const point=e=>{const r=stage.getBoundingClientRect();return {x:(e.clientX-r.left)/Math.max(1,r.width),y:(e.clientY-r.top)/Math.max(1,r.height)};};const endGesture=g=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',onUp);window.removeEventListener('pointercancel',onUp);if(!g)return;if(!g.moved){const field=g.node.querySelector('textarea');field?.focus();setTimeout(()=>field?.scrollIntoView({block:'center',inline:'nearest'}),300);}else syncBubbles();};function onMove(e){if(!bubbleGesture||e.pointerId!==bubbleGesture.pointer)return;if(Math.hypot(e.clientX-bubbleGesture.clientX,e.clientY-bubbleGesture.clientY)>10)bubbleGesture.moved=true;if(bubbleGesture.mode==='move'&&!bubbleGesture.moved)return;if(e.cancelable)e.preventDefault();const next=dragUpdate(bubbleGesture.mode,bubbleGesture.orig,bubbleGesture.start,point(e));const b=lettering?.bubbles.find(x=>x.id===bubbleGesture.id);if(!b)return;Object.assign(b,next);applyBubbleElement(bubbleGesture.node,b);const svg=stage.querySelector('.tail-layer');if(svg)svg.innerHTML=lettering.bubbles.map(tailMarkup).join('');}function onUp(e){if(!bubbleGesture||(e.pointerId!==undefined&&e.pointerId!==bubbleGesture.pointer))return;const g=bubbleGesture;bubbleGesture=null;endGesture(g);}stage.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-handle]');const node=e.target.closest('[data-bubble-id]');if(e.target.closest('textarea')){if(node){lettering.selected=node.dataset.bubbleId;markBubbleSelection();}return;}if(!node){lettering.selected=null;markBubbleSelection();return;}if(e.cancelable)e.preventDefault();const id=node.dataset.bubbleId;lettering.selected=id;markBubbleSelection();const b=lettering.bubbles.find(x=>x.id===id);if(!b)return;if(bubbleGesture)endGesture(bubbleGesture);bubbleGesture={id,pointer:e.pointerId,mode:handle?.dataset.handle||'move',start:point(e),orig:{...b},moved:false,clientX:e.clientX,clientY:e.clientY,node};try{node.setPointerCapture(e.pointerId);}catch{/* Safari still sends the later pointer events to the window listener. */}window.addEventListener('pointermove',onMove,{passive:false});window.addEventListener('pointerup',onUp);window.addEventListener('pointercancel',onUp);},{passive:false});}
function openBubbleEditor(id){const panel=panelById(id);if(!panel?.imageId){notify('Generate the panel image before adding speech bubbles.');return;}lettering={panelId:id,selected:null,bubbles:seedBubbles(panel).map(b=>({...b}))};lettering.selected=lettering.bubbles[0]?.id||null;drawBubbleEditor();const dialog=$('#lettering');if(!dialog.open)dialog.showModal();}
async function closeLettering(){if(!lettering)return;for(const b of lettering.bubbles)assertSafe(b.text||'');syncBubbles();await flush();lettering=null;bubbleGesture=null;const dialog=$('#lettering');if(dialog?.open)dialog.close();render();}
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Could not draw that panel.'));img.src=src;});}
async function downloadReaderPage(){const e=episode();const page=e?.pages?.[readerIndex];if(!page)return;const images=new Map();await Promise.all(BUBBLE_PRESETS.map(async preset=>{try{images.set(preset.id,await loadImage(preset.src));}catch{/* fallback shape */}}));const cellW=800,cellH=1000,gap=14,cols=page.layout==='single'?1:2,hero=page.layout==='hero'&&page.panels.length>1;const boxes=[];let cursor=gap,width=gap+cols*cellW+(cols-1)*gap+gap;if(hero){const span=cols*cellW+(cols-1)*gap;boxes.push({panel:page.panels[0],x:gap,y:cursor,w:span,h:Math.round(cellH*0.72)});cursor+=Math.round(cellH*0.72)+gap;page.panels.slice(1).forEach((panel,i)=>{const col=i%cols,row=Math.floor(i/cols);boxes.push({panel,x:gap+col*(cellW+gap),y:cursor+row*(cellH+gap),w:cellW,h:cellH});});const rows=Math.ceil((page.panels.length-1)/cols)||0;var height=cursor+(rows?rows*cellH+(rows-1)*gap:0)+gap;}else{page.panels.forEach((panel,i)=>{const col=i%cols,row=Math.floor(i/cols);boxes.push({panel,x:gap+col*(cellW+gap),y:gap+row*(cellH+gap),w:cellW,h:cellH});});const rows=Math.ceil(page.panels.length/cols)||1;var height=gap+rows*cellH+(rows-1)*gap+gap;}const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const draw=async(useImages)=>{const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);for(const box of boxes){ctx.save();ctx.beginPath();ctx.rect(box.x,box.y,box.w,box.h);ctx.clip();ctx.fillStyle='#fbe3ec';ctx.fillRect(box.x,box.y,box.w,box.h);if(box.panel.imageId){const url=await assetURL(box.panel.imageId);if(url){const img=await loadImage(url);const cover=coverRect(img.naturalWidth||img.width,img.naturalHeight||img.height,box.w,box.h);ctx.drawImage(img,box.x+cover.x,box.y+cover.y,cover.w,cover.h);}}if(box.panel.bubbles?.length)paintBubbles(ctx,{x:box.x,y:box.y,w:box.w,h:box.h},box.panel.bubbles,useImages?images:new Map());ctx.restore();}};await draw(true);let blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob){await draw(false);blob=await new Promise((r,j)=>canvas.toBlob(b=>b?r(b):j(Error('Could not export this page.')),'image/png'));}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`comic-page-${readerIndex+1}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Page download started. Bubbles are drawn on top of the art.');}
async function generateReference(){draft=collectCharacter();validateCharacter(draft);const inked=hasTattoos(draft);const scene=inked?'The same fictional adult in all three views. Consistent facial features, adult proportions, hair, and tattoo placement. Outfit or nudity follows the description. No text or labels.':'The same fictional adult in all three views. Consistent facial features, adult proportions, and hair. Outfit or nudity follows the description. No text or labels.';const prompt=panelPrompt({style:STYLE,camera:'Character design turnaround, front side and back on a plain studio background',scene,characters:[draft],limit:imagePromptLimit(settings.imageModel,provider.models),sheet:true});const blob=await provider.image(prompt,draft.refId?[draft.refId]:[],[draft],{seed:characterSeed(draft.id),negativePrompt:negativePromptFor([draft],{sheet:true}),sheet:true});draft.refId=await putAsset(blob);drawCharacterForm();notify('Reference ready. Save the character to keep it in your cast.');}
async function generatePortrait(){draft=collectCharacter();validateCharacter(draft);const prompt=portraitPrompt({style:series()?.style||STYLE,characters:[draft],limit:imagePromptLimit(settings.imageModel,provider.models)});const blob=await provider.image(prompt,[],[draft],{seed:characterSeed(draft.id+':portrait'),negativePrompt:negativePromptFor([draft],{sheet:true}),portrait:true});draft.portraitId=await putAsset(blob);drawCharacterForm();notify('Likeness portrait ready. Save the character to approve it.');}
function openReader(){if(!episode()?.pages.length){notify('Plan or add at least one page before opening the reader.');return;}readerIndex=0;drawReader();$('#reader').showModal();}
function drawReader(){const e=episode(),p=e.pages[readerIndex];$('#readerContent').innerHTML=`<div class="reader-toolbar"><div><p class="eyebrow" style="margin:0">${esc(series().title)}</p><strong>${esc(e.title)}</strong></div><div class="row">${button('↓ Page','download-page','secondary')}${button('✕','close-reader','secondary','aria-label="Close reader"')}</div></div><div class="comic-page ${p.layout}" id="swipePage">${p.panels.map(x=>`<div class="panel-art" data-preview="${x.id}">${preview(x,{edit:true})}</div>`).join('')}</div><div class="reader-controls">${button('← Previous','prev-page','secondary',readerIndex===0?'disabled':'')}<span class="muted" aria-live="polite">Page ${readerIndex+1} / ${e.pages.length}</span>${button('Next →','next-page','secondary',readerIndex===e.pages.length-1?'disabled':'')}</div><p class="reader-note">Swipe left / right to turn pages · Bubbles opens the lettering editor · Page downloads the art with bubbles on top</p>`;hydrate($('#reader'));}
function moveReader(delta){const n=readerIndex+delta;if(n>=0&&n<episode().pages.length){readerIndex=n;drawReader();$('#reader').scrollTop=0;}}
function sample(){if(lib.characters.length>98||lib.series.length>=100)throw Error('Library limit reached.');const a={id:uid(),name:'Mira Vale',age:32,fictional:true,description:'An expressive adult woman with warm brown skin, amber eyes, and a silver eyebrow piercing.',personality:'Fearless, wry, quietly affectionate. Speaks in short, warm observations.',backstory:'A cartographer who maps abandoned orbital gardens with her partner.',body:'Athletic adult build',hair:'Dark curls in a loose bun',outfit:'Copper flight jacket, navy trousers, and practical boots',tattoos:'Fine geometric constellation on the left forearm',refId:null};const b={...a,id:uid(),name:'Rowan Ash',age:35,description:'A broad-shouldered adult man with olive skin, green eyes, and a neatly trimmed beard.',personality:'Patient, curious, dry humor.',backstory:'A former botanical engineer and Mira’s partner.',hair:'Short wavy black hair',outfit:'A charcoal field coat over a moss-green shirt',tattoos:'An abstract leaf pattern on the right wrist'};lib.characters.push(a,b);const e={id:uid(),title:'The garden above the clouds',script:'The last shuttle leaves Mira and Rowan at the edge of an abandoned orbital garden. Amber light spills through the glass canopy.\n\nMira unfolds a paper map. “You said this place was empty.” Rowan smiles at the wildflowers growing through the floor. “I said nobody lived here.”\n\nThey find a bench overlooking the blue planet. Mira leans against Rowan’s shoulder. For the first time all week, neither of them has anywhere else to be.',previousScript:'',cast:[a.id,b.id],pages:[]};const s={id:uid(),title:'After the Last Shuttle',synopsis:'Two grown-up explorers finding extraordinary places, and a little more time for each other.',style:STYLE,episodes:[e]};lib.series.push(s);sid=s.id;eid=e.id;tab='write';save();render();notify('Sample loaded. Try AI polish, then Plan pages — demo mode uses no API.');}
async function generateStandaloneImage(){const draft=readImageDraft();const scene=String(draft.prompt||'').trim();const style=String(draft.style||'').trim();if(!scene)throw Error('Describe the image first.');if(gallery.length>=STANDALONE_LIMIT)throw Error('Delete a saved image first. This device keeps up to 200 standalone images.');const ids=[...new Set((draft.cast||[]).filter(id=>lib.characters.some(c=>c.id===id)))];const chars=ids.map(id=>lib.characters.find(c=>c.id===id)).filter(Boolean);for(const c of chars)validateCharacter(c);assertSafe([scene,style,...chars.map(characterText)].join('\n'),chars);const job=standaloneImageJob({prompt:scene,style,cast:ids,characters:chars,limit:imagePromptLimit(imageModelId(),provider.models),likeness:settings.likenessMode===true});const opts={seed:job.seed,portraitIds:settings.likenessMode?job.portraitIds:[]};if(settings.likenessMode&&!job.characters.length)opts.forceGenerate=true;const blob=await provider.image(job.prompt,job.referenceIds,job.characters,opts);const imageId=await putAsset(blob);await putStandalone({id:uid(),prompt:scene,style,camera:'Medium shot, eye level',cast:ids,imageId,createdAt:Date.now()});gallery=await listStandalone();render();document.querySelector('[data-image-result]')?.scrollIntoView({block:'start'});notify(settings.demo?'Demo image created locally. No credits used.':'Image saved on this device.');}
async function downloadStandaloneImage(id){const shot=gallery.find(s=>s.id===id);if(!shot)return;const asset=await getAsset(shot.imageId);if(!asset?.blob)throw Error('That image is no longer on this device.');const url=URL.createObjectURL(asset.blob);const ext=asset.blob.type==='image/png'?'png':asset.blob.type==='image/webp'?'webp':'jpg';const a=document.createElement('a');a.href=url;a.download=`comic-studio-image.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Image download started.');}
async function deleteStandaloneImage(id){const shot=gallery.find(s=>s.id===id);if(!shot)return;if(!await ask('Delete this image?','This removes it from the image gallery on this device. Series and episodes are not changed.','Delete'))return;await deleteStandalone(shot.id);gallery=gallery.filter(s=>s.id!==shot.id);if(!assetIds(lib).includes(shot.imageId)&&!gallery.some(s=>s.imageId===shot.imageId))await forgetAssets([shot.imageId]);render();notify('Image deleted from this device.');}
async function exportBackup(){await flush();const backup=await exportLibrary(lib);const blob=new Blob([JSON.stringify(backup)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`comic-studio-${new Date().toLocaleDateString('en-CA')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);localStorage.setItem('cs_last_backup',new Date().toISOString());const stamp=document.querySelector('#lastBackup');if(stamp)stamp.textContent=lastBackupLabel();notify('Backup download started. Save it somewhere private. API keys were excluded.');}
async function importBackup(file){if(!file)return;if(file.size>100*1024*1024)throw Error('Backups over 100 MB are not supported in v1.');let raw;try{raw=JSON.parse(await file.text());}catch{throw Error('That file is not valid JSON.');}if(!await ask('Replace your library?',`Import “${file.name}” and replace the stories on this device? A backup from this version also replaces standalone images. An older backup leaves them in place. Connection settings stay unchanged.`,'Replace library'))return;await flush();lib=await importLibrary(raw);gallery=await listStandalone();for(const u of assetURLs.values())URL.revokeObjectURL(u);assetURLs.clear();sid=eid=null;nav='library';render();notify('Library restored. Keys and connection settings were not imported.');}
function markUnsaved(n){if(!n?.closest)return;const modal=n.closest('#modal, #lettering');if(modal){const form=n.closest('form');if(form)form.dataset.dirty='1';else modal.dataset.dirty='1';}const settings=n.closest('#settingsForm');if(settings)settings.dataset.dirty='1';}
function unsavedWork(){if(bubbleGesture)return true;const modal=document.getElementById('modal');if(modal?.open&&(modal.dataset.dirty==='1'||modal.querySelector('[data-dirty="1"]')))return true;const letter=document.getElementById('lettering');if(letter?.open&&(letter.dataset.dirty==='1'||letter.querySelector('[data-dirty="1"]')))return true;const settings=document.getElementById('settingsForm');if(settings?.dataset.dirty==='1')return true;return false;}
function readReloadStamp(){try{return sessionStorage.getItem(SW_RELOAD_KEY)||'';}catch{return '';}}
function updateReadyControl(){let el=document.getElementById('updateReady');if(!el){el=document.createElement('button');el.type='button';el.id='updateReady';el.hidden=true;el.textContent='Update ready - tap to reload';document.body.append(el);}if(!el.dataset.bound){el.dataset.bound='1';el.addEventListener('click',()=>{reloadUpdatedApp();});}return el;}
function showUpdateReady(){const el=updateReadyControl();el.hidden=false;el.textContent='Update ready - tap to reload';}
async function reloadUpdatedApp(){if(updateReloadArmed)return;updateReloadArmed=true;try{await flush();}catch{/* The library write is best-effort. Never delete it to apply an update. */}try{sessionStorage.setItem(SW_RELOAD_KEY,String(Date.now()));}catch{}location.reload();}
function onControllerChange(){if(updateReloadArmed||recentUpdateReload(readReloadStamp(),Date.now()))return;if(shouldDeferUpdateReload({busy,batch:!!batchAbort,unsaved:unsavedWork()})){showUpdateReady();return;}reloadUpdatedApp();}
async function checkForUpdates(){if(updateReloadArmed)return;updateReloadArmed=true;try{const reg=swRegistration||await navigator.serviceWorker?.getRegistration?.();try{await reg?.update();}catch{/* A failed update check still drops the stale page cache. */}try{const keys=await caches.keys();await Promise.all(keys.filter(isAppShellCache).map(k=>caches.delete(k)));}catch{/* Cache Storage can be missing. Still reload so the browser fetches the shell. */}try{await flush();}catch{/* Keep the library write best-effort; never delete it. */}try{sessionStorage.setItem(SW_RELOAD_KEY,String(Date.now()));}catch{}location.reload();}catch(e){updateReloadArmed=false;notify('Could not check for updates. Your library was not changed.',true);}}
const actions={
  close:()=>closeModal(),
  'new-series':()=>{if(lib.series.length>=100)throw Error('V1 supports up to 100 series.');seriesForm();},
  'edit-series':()=>seriesForm(series()),
  'open-series':b=>{sid=b.dataset.id;eid=null;render();window.scrollTo(0,0);},
  'back-library':()=>{sid=eid=null;render();},
  'back-series':()=>{eid=null;render();},
  'new-episode':()=>{if(series().episodes.length>=200)throw Error('V1 supports up to 200 episodes per series.');episodeForm();},
  'open-episode':b=>{eid=b.dataset.id;tab='write';render();window.scrollTo(0,0);},
  'new-character':()=>{if(lib.characters.length>=100)throw Error('V1 supports up to 100 characters.');characterForm();},
  'edit-character':b=>characterForm(lib.characters.find(c=>c.id===b.dataset.id)),
  'remove-reference':()=>{draft=collectCharacter();draft.refId=null;drawCharacterForm();},
  'remove-portrait':()=>{draft=collectCharacter();draft.portraitId=null;drawCharacterForm();},
  'use-reference-portrait':()=>{draft=collectCharacter();if(!draft.refId)throw Error('Upload a reference image first.');draft.portraitId=draft.refId;drawCharacterForm();notify('This reference is the likeness portrait. Save the character to approve it.');},
  'generate-reference':()=>again(generateReference)(),
  'generate-portrait':()=>again(generatePortrait)(),
  polish:()=>again(polish)(),plan:()=>again(plan)(),
  'generate-comic':()=>again(()=>generateComic(false))(),
  'resume-comic':()=>again(()=>generateComic(true))(),
  'cancel-batch':()=>{if(batchAbort)batchAbort.abort();},
  'edit-bubbles':b=>openBubbleEditor(b.dataset.id),
  'add-bubble':b=>{if(!lettering)return;const count=lettering.bubbles.length;const bubble=createBubble(b.dataset.preset,{x:0.08+(count%3)*0.06,y:0.06+(count%4)*0.1});lettering.bubbles.push(bubble);lettering.selected=bubble.id;drawBubbleEditor();syncBubbles();},
  'flip-tail':()=>{if(!lettering)return;const b=lettering.bubbles.find(x=>x.id===lettering.selected);if(!b)return;Object.assign(b,flipTail(b));drawBubbleEditor();syncBubbles();},
  'delete-bubble':()=>{if(!lettering)return;lettering.bubbles=lettering.bubbles.filter(b=>b.id!==lettering.selected);lettering.selected=lettering.bubbles.at(-1)?.id||null;drawBubbleEditor();syncBubbles();},
  'close-lettering':()=>closeLettering(),
  'download-page':()=>run(downloadReaderPage),
  'apply-polish':async()=>{const e=episode(),value=$('#polishResult').value;assertSafe(value,selectedCharacters());e.previousScript=e.script;e.script=value;await save();closeModal();render();notify('Polish applied. Your previous draft is available with Undo last polish.');},
  'undo-polish':async()=>{const e=episode();[e.script,e.previousScript]=[e.previousScript,e.script];await save();render();},
  'generate-panel':b=>{const id=b.dataset.id;return again(()=>generatePanel(id))();},
  'add-page':async()=>{const e=episode();const count=e.pages.reduce((n,p)=>n+p.panels.length,0);if(e.pages.length>=EPISODE_MAX_PAGES||count>=EPISODE_MAX_PANELS)throw Error(`Episode limit: ${EPISODE_MAX_PAGES} pages / ${EPISODE_MAX_PANELS} panels.`);e.pages.push({id:uid(),layout:'two',panels:[newPanel(e.cast)]});await save();render();},
  'add-panel':async b=>{const e=episode(),p=e.pages.find(p=>p.id===b.dataset.id);const count=e.pages.reduce((n,p)=>n+p.panels.length,0);if(p.panels.length>=PAGE_MAX_PANELS||count>=EPISODE_MAX_PANELS)throw Error(`Limit: ${PAGE_MAX_PANELS} panels per page / ${EPISODE_MAX_PANELS} per episode.`);p.panels.push(newPanel(e.cast));await save();render();},
  'remove-panel':async b=>{if(!await ask('Remove panel?','Its lettering and artwork will be removed from this storyboard.','Remove'))return;const e=episode(),p=e.pages.find(p=>p.panels.some(x=>x.id===b.dataset.id));p.panels=p.panels.filter(x=>x.id!==b.dataset.id);e.pages=e.pages.filter(p=>p.panels.length);await save();render();},
  'remove-page':async b=>{if(!await ask('Remove this page?','All its panels, lettering, and artwork will leave the storyboard.','Remove'))return;episode().pages=episode().pages.filter(p=>p.id!==b.dataset.id);await save();render();},
  read:()=>openReader(),'close-reader':()=>$('#reader').close(),'prev-page':()=>moveReader(-1),'next-page':()=>moveReader(1),
  sample:()=>sample(),export:()=>run(exportBackup),import:()=>$('#importFile').click(),
  'generate-image':()=>again(generateStandaloneImage)(),
  'download-image':b=>run(()=>downloadStandaloneImage(b.dataset.id)),
  'delete-image':b=>deleteStandaloneImage(b.dataset.id),
  'load-models':()=>run(async()=>{await provider.loadModels();render();const refs=provider.models.filter(isReferenceCapable).length;notify(`${provider.models.length} active models loaded, ${refs} can take reference images. Save a model choice in Settings.`);}),
  'persist-storage':async()=>{const granted=await navigator.storage?.persist?.();$('#storageStatus').textContent=granted?'Persistent storage granted. Still keep backups.':'The browser did not grant persistent storage. Export backups regularly.';},
  'check-updates':()=>checkForUpdates(),
  'delete-character':async b=>{
    const saved=lib.characters.find(c=>c.id===b.dataset.id);
    if(!saved)return;
    const name=String(saved.name||'').trim()||'this character';
    if(!await ask(`Delete ${name}?`,"This can't be undone. Export your library first if you might want them back.",'Delete character'))return;
    const result=deleteCharacter(lib,saved.id);
    lib=result.lib;
    if(draft?.id===saved.id)closeModal();
    await save();
    await forgetAssets(result.orphanAssetIds);
    render();
  },
  'delete-series':async()=>{
    const s=series();
    if(!s)return;
    const n=Array.isArray(s.episodes)?s.episodes.length:0;
    const title=String(s.title||'').trim()||'this series';
    if(!await ask(`Delete ${title}?`,`This series contains ${n} episode${n===1?'':'s'}. Deleting it removes those episodes and their panel art. Characters are not deleted. This can't be undone.`,'Delete series'))return;
    const result=deleteSeries(lib,s.id);
    lib=result.lib;
    if(sid===s.id){sid=null;eid=null;}
    dismissDeleted();
    if($('#modal')?.open)closeModal();
    await save();
    await forgetAssets(result.orphanAssetIds);
    render();
  },
  'delete-episode':async()=>{
    const e=episode();
    if(!e)return;
    const title=String(e.title||'').trim()||'this episode';
    if(!await ask(`Delete ${title}?`,'This removes the episode and its panel art. This can\'t be undone.','Delete episode'))return;
    const result=deleteEpisode(lib,e.id);
    lib=result.lib;
    if(eid===e.id)eid=null;
    dismissDeleted();
    await save();
    await forgetAssets(result.orphanAssetIds);
    render();
  }
};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(busy&&!['close-reader','prev-page','next-page','cancel-batch'].includes(b.dataset.action))return;if(b.dataset.nav){if(busy)return;await flush().catch(()=>{});nav=b.dataset.nav;sid=eid=null;render();window.scrollTo(0,0);return;}if(b.dataset.tab){if(busy)return;await flush().catch(()=>{});tab=b.dataset.tab;render();return;}const fn=actions[b.dataset.action];if(fn){try{await fn(b);}catch(e){notify(explainRequestError(e),true);}}});
$('#brand').addEventListener('click',async e=>{e.preventDefault();if(busy)return;await flush().catch(()=>{});nav='library';sid=eid=null;render();});
document.addEventListener('submit',async ev=>{ev.preventDefault();if(busy)return;const form=ev.target;try{
  if(form.id==='seriesForm'){const f=new FormData(form);const title=String(f.get('title')).trim(),synopsis=String(f.get('synopsis')).trim(),style=String(f.get('style')).trim();if(!title||!style)throw Error('Add a title and art style.');assertSafe([title,synopsis,style].join('\n'));let s=lib.series.find(s=>s.id===form.dataset.id);if(s)Object.assign(s,{title,synopsis,style});else{s={id:uid(),title,synopsis,style,episodes:[]};lib.series.push(s);}await save();closeModal();nav='library';sid=s.id;eid=null;render();}
  if(form.id==='episodeForm'){const f=new FormData(form),title=String(f.get('title')).trim();assertSafe(title);if(!title)throw Error('Add an episode title.');const e={id:uid(),title,script:'',previousScript:'',cast:lib.characters.map(c=>c.id),pages:[]};series().episodes.push(e);await save();closeModal();eid=e.id;tab='write';render();}
  if(form.id==='characterForm'){const c=collectCharacter();validateCharacter(c);const i=lib.characters.findIndex(x=>x.id===c.id);if(i>=0)lib.characters[i]=c;else lib.characters.push(c);await save();closeModal();render();notify('Character saved on this device.');if(await ask('Export a library backup?','This character, including any likeness portrait, is stored only in this browser. Export the library so a cleared cache does not erase it. Connection settings and keys are not included.','Export library'))await exportBackup();}
  if(form.id==='settingsForm'){const f=new FormData(form);const localURL=localBase(String(f.get('localURL')).trim());const next={...settings,demo:f.has('demo'),localURL,allowCloudFallback:f.has('allowCloudFallback'),textModel:String(f.get('textModel')).trim()||'most_uncensored',imageModel:String(f.get('imageModel')).trim()||'chroma',likenessMode:f.has('likenessMode'),likenessModel:String(f.get('likenessModel')||'').trim()||DEFAULT_LIKENESS_MODEL,panelCount:settings.panelCount};if(!next.demo&&settings.demo&&!await ask('Enable live requests?','This mode connects to your selected providers. Each Venice generation asks before spending. Prompts and supported reference images leave this device.','Enable live mode'))return;settings=next;provider.settings=settings;writeSettings(settings);for(const [key,field] of [['cs_k','veniceKey'],['cs_local_k','localKey']]){const v=String(f.get(field)||'').trim();v?localStorage.setItem(key,v):localStorage.removeItem(key);}render();notify('Settings saved on this device.');}
}catch(e){notify(explainRequestError(e),true);}});
document.addEventListener('input',ev=>{const n=ev.target;markUnsaved(n);if(n.dataset?.imagePrompt)imageDraft.prompt=n.value;if(n.dataset?.imageStyle)imageDraft.style=n.value;n.closest?.('#modal, #lettering')?.querySelector('[data-dialog-notice]')?.remove();const e=episode();if(n.dataset.bind==='script'&&e){e.script=n.value;queueSave();}if(n.dataset.bind==='episode-title'&&e){e.title=n.value;queueSave();}if(n.dataset.bubbleText&&lettering){const b=lettering.bubbles.find(x=>x.id===n.dataset.bubbleText);if(!b)return;const next=n.value.slice(0,500);try{assertSafe(next);b.text=next;syncBubbles();}catch(err){n.value=b.text||'';notify(explainRequestError(err),true);}return;}if(n.dataset.bubbleFont&&lettering){const b=lettering.bubbles.find(x=>x.id===lettering.selected);if(!b)return;Object.assign(b,setFontSize(b,n.value));const node=document.querySelector(`#lettering [data-bubble-id="${b.id}"]`);if(node)applyBubbleElement(node,b);syncBubbles();return;}if(n.dataset.panelField){const p=panelById(n.dataset.id);if(!p)return;p[n.dataset.panelField]=n.value;queueSave();if(['dialogue','caption','bubblePosition','captionPosition'].includes(n.dataset.panelField)){document.querySelectorAll(`[data-preview="${p.id}"]`).forEach(previewNode=>{previewNode.innerHTML=preview(p,{edit:!!previewNode.closest('#reader')});hydrate(previewNode);});}}});
